{ id: "thermisch", cat: "Trauma / MANV", title: "Thermische Verletzungen", src: "KP S. 163–164", search: "verbrennung verbrühung inhalationstrauma",
  note: NF_NOTE,
  sections: [
    { h: "Therapie", items: ["keine aktive Kühlung durch den Rettungsdienst; bereits begonnene Kühlung beenden", "Wunden steril, trocken, nicht verklebend abdecken; Wärmeerhalt (Rettungsmittel vorheizen, angewärmte Infusionen, Wärmedecken), Ziel > 36 °C", "i.v.-Zugang (ggf. 2.) in nicht verbrannter Haut, ggf. i.o.", "VEL: Erwachsene max. 1 l/h; Kinder max. 10 ml/kgKG/h, Bolus 20 ml/kgKG; Kinder < 10 % VKOF: Zugang kann entfallen, wenn KH < 30 min", "Analgesie bei NRS ≥ 3; keine Cortison-Gabe in jeglicher Form", "Intubation allein bei V.a. Inhalationstrauma beim respiratorisch stabilen Pat. vermeiden", "VKOF schätzen: Handfläche des Betroffenen = 1 %"] },
    { h: "Inhalationstrauma / CO", items: ["Hinweise: Rauch-/Flammenexposition in geschlossenen Räumen, Bewusstlosigkeit, verbranntes Gesicht, versengte Haare, Ruß, Stridor, Ödem", "CO-Intoxikation stets mitdenken; bei Bronchialobstruktion ggf. ß-Sympathomimetika"] },
    { h: "Zentrum für Brandverletzte", items: ["Grad 2 ≥ 10 % KOF; Grad 3; Hände, Gesicht, Genitalien; Elektrizität inkl. Blitz; Chemikalien; Inhalationstrauma; erschwerende Begleiterkrankungen / -verletzungen; besonderer Betreuungsbedarf", "Zuweisung nach regionalem Konzept"] } ],
  meds: ["vel"] },
{ id: "rettung", cat: "Trauma / MANV", title: "Patientenzentrierte Rettung (eingeklemmte Person)", src: "KP S. 165–166", search: "eingeklemmt technische rettung vu vfdb",
  note: NF_NOTE, flags: [],
  sections: [
    { h: "Einsatzstelle", items: ["Verkehrsabsicherung, Brandschutz, Fahrzeugstabilisierung, Eigenschutz (Helm, Schutzbrille, FFP2, Schnittschutzhandschuhe …)", "RD-Fahrzeuge ca. 50 m Abstand; 5- und 10-m-Kreis, möglichst nur 1 „innerer Retter“", "Unfallkinematik, Zugang schaffen (Türen, Verglasung)"] },
    { h: "Entscheidung", items: ["Atmung insuffizient (AF < 8 / > 30), nicht beatembar, nicht kreislaufstabil (RRsyst ≤ 90, HF ≥ 120), SHT mit Hirndruckzeichen ➜ SOFORT-RETTUNG: technische Rettung nur soweit zur Befreiung nötig, achsengerecht nur mit einfachen Mitteln", "vitale Gefährdung zu erwarten ➜ SCHNELLE RETTUNG: Befreiung in kurzer Zeit, raumschaffend, achsengerecht", "sonst Basisversorgung (Patientenschutz, Blutstillung, HWS, O2, Zugang, Infusion, Wärme, Monitoring, Analgesie) und schonende Rettung", "Transport ins Traumazentrum; > 20 min ➜ RTH"] } ] },
{ id: "mstart", cat: "Trauma / MANV", title: "MANV – Vorsichtung nach mSTaRT", src: "KP S. 167–170", search: "manv mstart sichtung vorsichtung triage",
  note: NF_NOTE, flags: [],
  sections: [
    { h: "Algorithmus (max. 45–60 s pro Pat.)", items: ["gehfähig ➜ Kategorie III (Sammelpunkt), erneute Sichtung so bald wie möglich", "starke äußere Blutung ➜ Tourniquet ➜ I", "keine Atmung nach Überstrecken des Kopfes ➜ tot / keine Überlebenschance", "AF Erw. > 30 oder < 10/min (Kinder > 40 oder < 10) ➜ I", "Radialispuls nicht tastbar oder PF > 120/min (Kinder: Rekap Stirn > 3 s) ➜ I", "folgt einfachen Aufforderungen nicht (Kind > 3 J.: reagiert nicht adäquat) ➜ I, stabile Seitenlage", "alle anderen ➜ II", "Kinder < 10 Jahre je nach Entwicklung nach Kinderkriterien"] },
    { h: "Behandlung bei Vorsichtung", items: ["grundsätzlich keine – außer Blutstillung, Kopf überstrecken bei Atemstillstand, stabile Seitenlage"] },
    { h: "Kennzeichnung", items: ["Kategorie I und EX: rotes Band (i.d.R. Oberarm); andere: weißes Band", "Vorsichtung ersetzt nicht die ärztliche Sichtung"] } ] },
{ id: "co", cat: "Trauma / MANV", title: "Intoxikation mit Kohlenstoffmonoxid (CO)", src: "KP S. 171–174", search: "co kohlenmonoxid rauchgas spco warngerät",
  note: NF_NOTE, flags: [],
  sections: [
    { h: "Eigenschutz – Warngerät", items: ["> 20 ppm Aufmerksamkeitsschwelle: Fenster/Türen öffnen, weiterarbeiten, Quelle suchen", "> 60 ppm Gefährdungsschwelle: zuerst lüften; sonst Pat. aus Gefahrenbereich (< 15 min) – schnelle Rettung; Feuerwehr", "> 200 ppm Rückzugsschwelle: sofortiger Rückzug, Feuerwehr, Maßnahmen nur mit Atemschutz", "> 500 ppm: alle Maßnahmen nur mit umluftunabhängigem Atemschutz", "Bei CO-Verdacht immer Feuerwehr nachalarmieren (MG: erst ab Warngrenzwert)"] },
    { h: "Patient", items: ["O2 15 l/min, FiO2 > 0,8; erwäge CPAP", "SpCO messen (Finger sauber, Durchblutung, Lichtschutz) – Screening, im Zweifel Klinik", "SpCO > 20 % oder bewusstlos ➜ HBO erwägen; bei Brand und V.a. Cyanid ➜ Antidot erwägen (NA)", "Kinder, Schwangere, kardiorespiratorisch Vorerkrankte besonders beachten", "Konventionelle Pulsoxymeter zeigen fälschlich hohe SpO2", "CO-Wert und SpCO dokumentieren, auch beim Personal"] },
    { h: "Symptome nach SpCO", items: ["< 5 %: evtl. leichte Kopfschmerzen", "6–20 %: zunehmende Kopfschmerzen, Luftnot", "21–30 %: starke Kopfschmerzen, Übelkeit, Schwindel, Müdigkeit", "31–40 %: + Brechreiz, Verwirrung", "41–50 %: Verwirrung, Synkopen, Tachykardie", "51–60 %: Krämpfe, Schock, Apnoe, Koma"] } ],
  meds: ["sauerstoff"] }
